public class DateTimeFormatter_parseInto_TriageGen0Test {

    private DateTimeFormatter formatter;
    private ReadWritableInstant mockInstant;
    private DateTimeParser mockParser;
    private Chronology mockChrono;
    private DateTimeZone mockZone;

    @Before
    public void setUp() {
        mockInstant = mock(ReadWritableInstant.class);
        mockParser = mock(DateTimeParser.class);
        mockChrono = mock(Chronology.class);
        mockZone = mock(DateTimeZone.class);

        // Default behavior for the mock instant
        when(mockInstant.getMillis()).thenReturn(0L);
        when(mockInstant.getChronology()).thenReturn(mockChrono);
        when(mockChrono.getZone()).thenReturn(mockZone);
        when(mockZone.getOffset(anyLong())).thenReturn(0);

        // Mock chronology behavior for year extraction
        LocalDate mockLocalDate = mock(LocalDate.class);
        when(mockChrono.year()).thenReturn(mockLocalDate);
        when(mockLocalDate.get(any(org.joda.time.TemporalField.class))).thenReturn(2023);

        // Mock parser behavior
        when(mockParser.parseInto(any(DateTimeParserBucket.class), anyString(), anyInt())).thenReturn(5);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testParseInto_NullInstant_ThrowsException() {
        // Using a real formatter but passing null instant
        DateTimeFormatter realFormatter = new DateTimeFormatterBuilder().appendPattern("yyyyMMdd").toFormatter();
        realFormatter.parseInto(null, "20230101", 0);
    }

    @Test
    public void testParseInto_StandardParsing() {
        // We use a real builder to get a valid internal parser state
        formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMdd")
                .toFormatter();

        // Since we cannot easily inject the mock parser into the private field of a real DateTimeFormatter 
        // without reflection, for a pure unit test of the logic provided in the snippet, 
        // we assume the environment allows the call to requireParser().
        // In a real Joda scenario, we'd use the builder.

        ReadWritableInstant instant = new org.joda.time.format.MutableDateTime(0);
        String text = "20230101";
        int position = 0;

        int result = formatter.parseInto(instant, text, position);

