    public void testParseInto_WithOffsetParsedTrue() {
        // Testing the branch: if (iOffsetParsed && bucket.getOffsetInteger() != null)
        formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMddHHmmZ")
                .withOffsetParsed()
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(0);
        String text = "202301011200+0500";

        int result = formatter.parseInto(instant, text, 0);

        // Verification of state change would happen here
