    @Test
    public void testParseInto_WithZoneInBucket() {
        // Testing the branch: else if (bucket.getZone() != null)
        formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMdd")
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(0);
        String text = "20230101";

        formatter.parseInto(instant, text, 0);
    }

    @Test
    public void testParseInto_WithFixedZone() {
        // Testing the branch: if (iZone != null)
        DateTimeZone fixedZone = DateTimeZone.forID("UTC");
        formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMdd")
                .toFormatter()
                .withZone(fixedZone);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(0);
        String text = "20230101";

        formatter.parseInto(instant, text, 0);
        assertEquals(fixedZone, instant.getZone());
    }

    @Test
    public void testParseInto_WithPivotYear() {
        // Testing the branch involving iPivotYear
        formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyMMdd")
                .withPivotYear(2000)
                .toFormatter();

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(0);
        String text = "230101";

        formatter.parseInto(instant, text, 0);
    }

    @Test
    public void testParseInto_WithLocale() {
        // Testing the branch involving iLocale
        formatter = new DateTimeFormatterBuilder()
                .appendPattern("yyyyMMdd")
                .toFormatter()
                .withLocale(Locale.FRENCH);

        org.joda.time.MutableDateTime instant = new org.joda.time.MutableDateTime(0);
        String text = "20230101";

        formatter.parseInto(instant, text, 0);
        assertEquals(Locale.FRENCH, formatter.getLocale());
    }
}
